import json,re,html
out={}
for f in ['products/research/manager-invoices-44200-full.json','products/research/manager-batch-65600-full.json']:
  d=json.load(open('/workspace/'+f))
  posts=d.get('post_stream',{}).get('posts',[])
  rows=[]
  for p in posts:
    t=re.sub(r'<[^>]+>',' ',p.get('cooked',''));t=html.unescape(re.sub(r'\s+',' ',t)).strip()
    links=re.findall(r'href="(https?://[^"]+)"',p.get('cooked',''))
    rows.append({'n':p.get('post_number'),'date':p.get('created_at'),'staff':p.get('staff') or p.get('moderator') or p.get('admin'),'text':t,'links':[l for l in links if 'manager.io' in l and '/t/' not in l and '/u/' not in l]})
  out[f]={'title':d.get('title'),'posts_count':d.get('posts_count'),'stream_len':len(d.get('post_stream',{}).get('stream',[])),'posts':rows}
json.dump(out,open('/workspace/products/services/manager-mapping/thread-extract.json','w'),indent=1,ensure_ascii=False)
for f,v in out.items():
  print(f,v['title'],v['posts_count'],v['stream_len'],len(v['posts']))
  for r in v['posts']: print(r['n'],r['date'][:10],'S' if r['staff'] else '',len(r['text']),r['links'][:3])
